INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(c.id,7),c.id,
 CASE WHEN c.id LIKE 'claim.v0200.identification_%' THEN 'source.mesopotamia.inanna_ishtar.oracc'
      WHEN c.id LIKE 'claim.v0200.anzu_%' OR c.id LIKE 'claim.v0200.ninurta_%' THEN 'source.mesopotamia.anzu_ninurta.oracc'
      ELSE 'source.ugaritic.baal_corpus_ktu15_16.goettingen' END,
 CASE WHEN c.id LIKE 'claim.v0200.identification_%' THEN 'Inana/Ištar specialist overview'
      WHEN c.id LIKE 'claim.v0200.anzu_%' OR c.id LIKE 'claim.v0200.ninurta_%' THEN 'Anzu narrative synopsis'
      ELSE 'KTU corpus overview and concordance' END,
 CASE WHEN c.knowledge_layer='ARCHAEOLOGICAL' THEN 'ARCHAEOLOGICAL' WHEN c.knowledge_layer='MYTHIC_NARRATIVE' OR c.knowledge_layer='TEXTUAL_WITNESS' THEN 'ANCIENT_TEXT' ELSE 'MODERN_SCHOLARSHIP' END,
 'SUPPORTS',c.confidence,'v0.20 source-scoped evidence'
FROM claims c WHERE c.id LIKE 'claim.v0200.%';

